/**
 * FYF Official Mascot Asset & Data URI Definition
 * Source: /projects/FYF_AI_Brand/assets/facebook/source/fyf-mascot-presenting-transparent.png
 */

export const MASCOT_PRESENTING_BASE64_DATA_URI = "data:image/png;base64,";

/**
 * Returns an SVG <image> tag embedding the official FYF Presenting Origami Mascot.
 */
export function renderMascotSvgVector(x: number, y: number, width: number, height: number): string {
  return `
    <g id="fyf-mascot-presenting">
      <image href="${MASCOT_PRESENTING_BASE64_DATA_URI}" x="${x}" y="${y}" width="${width}" height="${height}" preserveAspectRatio="xMidYMid meet" />
    </g>
  `.trim();
}
